using System;
using System.IO;
using System.Linq;
using System.Diagnostics;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using TasiaCraft;
public static class ExportCommitTest {
 static int passed;static string root,log;static void Check(bool ok,string label){if(!ok)throw new Exception(label);passed++;File.AppendAllText(log,"PASS "+label+Environment.NewLine);}
 static Exception Fail(Action action){try{action();}catch(Exception e){return e;}throw new Exception("Expected export failure");}
 static void Clean(){Check(Directory.GetFiles(root,".tasia-render-*.mp4").Length==0,"render temporary file cleanup");}
 public static int Main(string[] args){root=args[0];Directory.CreateDirectory(root);log=Path.Combine(root,"results.txt");File.WriteAllText(log,"");try{
  string source=Path.Combine(root,"source.mp4"),output=Path.Combine(root,"復元 export.mp4");Engine.Run("ffmpeg","-y -v error -f lavfi -i color=red:s=320x180:r=30 -f lavfi -i sine=frequency=440:sample_rate=48000 -t 1 -c:v libopenh264 -c:a aac "+Engine.Quote(source));byte[] originalSource=File.ReadAllBytes(source);var media=Engine.Probe(source);var project=new Project{Width=320,Height=180};project.Media.Add(media);project.Clips.Add(new Clip{MediaId=media.Id,Duration=.5,NativeSize=true});var json=new JavaScriptSerializer();string model=json.Serialize(project);var events=new List<string>();Engine.Render(project,output,events.Add);Check(File.Exists(output),"new Unicode export created");Check(events.Contains("Finalizing export..."),"finalization status emitted");Check(events.Last()=="Export complete","completion emitted after commit");Clean();byte[] first=File.ReadAllBytes(output);project.Clips[0].Volume=.5;FileStream held=null;Task released=null;Stopwatch commit=null;
  Engine.Render(project,output,message=>{if(message=="Finalizing export..."){held=new FileStream(output,FileMode.Open,FileAccess.Read,FileShare.ReadWrite);commit=Stopwatch.StartNew();released=Task.Run(()=>{Thread.Sleep(300);held.Dispose();});}});released.Wait();commit.Stop();Check(commit.ElapsedMilliseconds>=250&&commit.ElapsedMilliseconds<6000,"temporary Windows no-delete lock recovers in bounded time");Check(!File.ReadAllBytes(output).SequenceEqual(first),"replacement publishes the new encoded output");Clean();var info=Engine.Probe(output);Check(info.HasAudio,"recovered export retains audio stream");Check(Math.Abs(info.Duration-.5)<.12,"recovered export duration preserved");string rgb=Path.Combine(root,"frame.rgb");Engine.Run("ffmpeg","-y -v error -ss 0.2 -i "+Engine.Quote(output)+" -frames:v 1 -pix_fmt rgb24 -f rawvideo "+Engine.Quote(rgb));var pixels=File.ReadAllBytes(rgb);int center=(90*320+160)*3;Check(pixels.Length==320*180*3&&pixels[center]>200&&pixels[center+1]<50&&pixels[center+2]<50,"recovered export decoded picture preserved");string pcm=Path.Combine(root,"audio.pcm");Engine.Run("ffmpeg","-y -v error -i "+Engine.Quote(output)+" -vn -ac 1 -ar 48000 -f s16le "+Engine.Quote(pcm));var samples=File.ReadAllBytes(pcm);double sum=0;for(int i=0;i+1<samples.Length;i+=2){double sample=BitConverter.ToInt16(samples,i)/32768.0;sum+=sample*sample;}Check(Math.Sqrt(sum/(samples.Length/2))>.01,"recovered export decoded audio audible");
  byte[] previous=File.ReadAllBytes(output);bool complete=false;Exception failure;commit=null;using(var locked=new FileStream(output,FileMode.Open,FileAccess.Read,FileShare.ReadWrite)){failure=Fail(()=>Engine.Render(project,output,message=>{if(message=="Finalizing export...")commit=Stopwatch.StartNew();if(message=="Export complete")complete=true;}));}commit.Stop();Check(failure is IOException,"permanent destination lock reports IO failure");Check(commit.ElapsedMilliseconds>=1300&&commit.ElapsedMilliseconds<6000,"permanent lock commit retries are bounded");Check(!complete,"failed commit never reports completion");Check(File.ReadAllBytes(output).SequenceEqual(previous),"permanent lock preserves previous output bytes");Clean();
  File.SetAttributes(output,FileAttributes.ReadOnly);try{failure=Fail(()=>Engine.Render(project,output,null));Check(failure is IOException||failure is UnauthorizedAccessException,"read-only output rejected");Check(File.ReadAllBytes(output).SequenceEqual(previous),"read-only failure preserves previous bytes");Clean();}finally{File.SetAttributes(output,FileAttributes.Normal);}
  failure=Fail(()=>Engine.Render(project,Path.Combine(root,"missing","out.mp4"),null));Check(failure!=null&&!Directory.Exists(Path.Combine(root,"missing")),"missing destination directory fails without creating it");Clean();failure=Fail(()=>Engine.Render(project,source,null));Check(failure is InvalidDataException,"source-media destination rejected");Check(File.ReadAllBytes(source).SequenceEqual(originalSource),"all export attempts preserve source media bytes");project.Clips[0].Volume=1;Check(json.Serialize(project)==model,"all export attempts leave project unchanged");File.AppendAllText(log,"PASS total "+passed+Environment.NewLine);return 0;
 }catch(Exception ex){File.AppendAllText(log,"FAIL "+ex+Environment.NewLine);return 1;}}
}
